return async function(config, ctx) {
  const baseUrl = String(config.baseUrl || '').trim().replace(/\/$/, '');
  const token = String(config.token || '').trim();
  const version = config.version === 'v1' ? 'v1' : 'v2';
  if (!baseUrl || !token) {
    return { options: [], help: '请先填写站点地址和 Token' };
  }

  const url = version === 'v1' ? baseUrl + '/api/v1/strategies' : baseUrl + '/api/v2/group';
  const res = await ctx.fetch(url, {
    headers: {
      'Authorization': 'Bearer ' + token,
      'Accept': 'application/json, text/plain, */*'
    }
  });

  if (!res.ok) throw new Error('HTTP ' + res.status);
  const json = res.body;

  let items = [];
  if (version === 'v1') {
    if (!json || !json.status) throw new Error((json && (json.message || json.msg)) || '获取策略列表失败');
    items = Array.isArray(json.data) ? json.data : ((json.data && json.data.strategies) || []);
  } else {
    if (!json || (json.status !== true && json.status !== 'success')) throw new Error((json && (json.message || json.msg)) || '获取存储列表失败');
    items = (json.data && json.data.storages) || [];
  }

  const options = items.map(item => ({
    label: item.name || ('ID ' + item.id),
    value: String(item.id)
  }));

  const result = {
    options,
    help: version === 'v1' ? '已从 API 拉取策略列表' : '已从 API 拉取存储列表'
  };

  if (options.length === 1) {
    result.value = options[0].value;
  }

  return result;
}

