return async function(config, file, ctx) {
  const baseUrl = String(config.baseUrl || '').trim().replace(/\/$/, '');
  const version = config.version === 'v1' ? 'v1' : 'v2';
  const token = String(config.token || '').trim();
  if (!baseUrl) throw new Error('Missing baseUrl');

  const uploadUrl = version === 'v1' ? baseUrl + '/api/v1/upload' : baseUrl + '/api/v2/upload';
  const blob = ctx.fileToBlob ? ctx.fileToBlob() : await (await fetch(file.data)).blob();
  const fd = new FormData();
  fd.append('file', blob, file.name);

  if (config.storageId) {
    fd.append(version === 'v1' ? 'strategy_id' : 'storage_id', String(config.storageId));
  }
  if (config.albumId) {
    fd.append('album_id', String(config.albumId));
  }

  const isPublic = config.isPublic === false ? '0' : '1';
  if (version === 'v1') {
    fd.append('permission', isPublic);
  } else {
    fd.append('is_public', isPublic);
  }

  const headers = {
    'Accept': 'application/json, text/plain, */*'
  };
  if (token) {
    headers['Authorization'] = 'Bearer ' + token;
  }

  const res = await ctx.fetch(uploadUrl, {
    method: 'POST',
    headers,
    body: fd
  });

  const json = res.body;
  if (!res.ok) {
    throw new Error((json && (json.message || json.msg)) || ('HTTP ' + res.status));
  }

  const success = version === 'v1'
    ? !!(json && json.status)
    : !!(json && (json.status === true || json.status === 'success'));

  if (!success) {
    throw new Error((json && (json.message || json.msg)) || 'Upload failed');
  }

  const data = (json && json.data) || {};
  let url = data.url || data.public_url || (data.links && (data.links.url || data.links.html || data.links.markdown));
  if (!url) throw new Error('Upload succeeded but no URL found in response');

  try {
    url = new URL(String(url), baseUrl + '/').href;
  } catch (_) {}

  return url;
}
